import{_ as s,o as t,c as a,a3 as o}from"./chunks/framework.DH50UWNB.js";const u=JSON.parse('{"title":"Older installations","description":"","frontmatter":{},"headers":[],"relativePath":"run/older-installations.md","filePath":"run/older-installations.md"}'),r={name:"run/older-installations.md"};function i(n,e,d,l,c,h){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="older-installations" tabindex="-1">Older installations <a class="header-anchor" href="#older-installations" aria-label="Permalink to &quot;Older installations&quot;">​</a></h1><p>Most installations need nothing from this page. If yours is older than one of these releases, do what its entry says; the entries are oldest first.</p><details class="details custom-block"><summary>Older than v1.3.0</summary><p>A repository connected to Claude Code before Wake had its plugin still has Wake&#39;s hooks in <code>.claude/settings.json</code>. Its session start says to run <code>wake connect claude-code</code> once, which removes them. Upgrade the CLI first: an older CLI copies the hooks back next to the plugin&#39;s, so they would run twice.</p></details><details class="details custom-block"><summary>Made with v1.3.0 or v1.3.1</summary><p>An installation made with v1.3 has a <code>wake-server</code> that downloads releases from a repository that is no longer public, so it cannot upgrade. Replace it once with the current one, then upgrade; your data and secrets are kept:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> installation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> director</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/dalodev/wake-dist/releases/latest/download/install.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wake-server</span></span>
<span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 700</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wake-server</span></span>
<span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./wake-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span></span></code></pre></div><p>A project connected to Claude Code by Wake 1.3 names that old repository as its plugin marketplace. Its next session start moves the entry to <code>wake-dist</code> and asks you to commit <code>.claude/settings.json</code>: commit it.</p></details><details class="details custom-block"><summary>Older than v1.10.1</summary><p><code>wake-server start</code> does not exist yet. Start Docker, then run <code>wake-server upgrade</code>, which brings it. To start Wake without upgrading, run <code>docker compose up -d</code> in <code>&lt;your installation directory&gt;</code>.</p></details><details class="details custom-block"><summary>Older than v2.2.0</summary><p>Your next upgrade still runs the <code>wake-server</code> you have, which checks the release&#39;s checksums but not their signature, does not pause Wake for the backup, and rolls back without restoring the database. Before it:</p><ol><li>Run <code>wake-server backup</code>.</li><li>When verifying the release matters to you, check its files by hand as in <a href="/wake-dist/docs/reference/verify-installer">Verify a download</a>, then run <code>wake-server upgrade --version v2.2.0</code>. Every upgrade after it verifies signatures.</li><li>After the upgrade, run <code>wake-server start</code> once. It gives the server its own storage user, adding two lines to <code>.env</code>, recreating the services and printing <code>The server now uses its own storage user, wake-server.</code> When they do not become healthy, it puts <code>.env</code> back as it was, starts them again with the storage&#39;s root keys, and exits <code>1</code>.</li></ol><p>Backups written before v2.2 are <code>backups/wake-&lt;version&gt;-&lt;UTC time&gt;.sql.gz</code> and hold the database only. <code>wake-server restore</code> reads them: it restores the database and keeps the evidence files. Upgrades never remove them; delete them by hand when you no longer need them.</p></details><details class="details custom-block"><summary>Older than v2.3.0</summary><p>The daily upgrade&#39;s crontab line appends to <code>auto-upgrade.log</code> without ever rotating it. It still counts as on. After upgrading, run <code>wake-server auto-upgrade on</code> once to rewrite the line in place; your other crontab lines stay as they are. The next <code>wake-server upgrade</code> rewrites it too.</p><p>The upgrade also brings the limits on the services&#39; container logs. The first <a href="/wake-dist/docs/reference/cleanup">cleanup</a> pass after it deletes the whole backlog of expired records and can take a while; its <code>records cleaned</code> log line says how long.</p></details><details class="details custom-block"><summary>Older than v2.4.0</summary><p>The upgrade to v2.4.0 still runs the <code>wake-server</code> you have, which keeps every upgrade backup and writes no <code>LICENSE</code>. Run <code>wake-server upgrade</code> once more afterwards: it finds nothing to upgrade and writes the release&#39;s <code>LICENSE</code>. The upgrades after it remove older upgrade backups.</p><p>Backups written before v2.4 do not record what wrote them, so upgrades never remove them. Delete them by hand from <code>backups/</code> when you no longer need them.</p><p>A <code>wake</code> CLI older than v2.4.0 looks for the server only in <code>WAKE_SERVER_DIR</code> and the default directory. When you installed with <code>--dir</code>, run <code>wake-server upgrade</code> there yourself, or set <code>WAKE_SERVER_DIR</code> before <code>wake upgrade</code>.</p></details>`,8)])])}const k=s(r,[["render",i]]);export{u as __pageData,k as default};
